export type PlayerRole = 'BATTER' | 'BOWLER' | 'ALL_ROUNDER' | 'WICKETKEEPER';
export type BowlingType = 'PACE' | 'SPIN' | 'NONE';

export interface PlayerStats {
  seasonRange: string;
  matches: number;
  innings: number;
  runs: number;
  battingAverage: number;
  strikeRate: number;
  fifties: number;
  hundreds: number;
  highestScore: string;
  wickets: number;
  bowlingAverage: number;
  economyRate: number;
  bestBowling: string;
  catches: number;
  stumpings: number;
  provenance: string;
}

export interface PlayerAuctionEvent {
  auctionSeason: string;
  auctionDate: string;
  auctionType: 'MEGA' | 'MINI' | 'RETENTION';
  auctionStatus: 'SOLD' | 'UNSOLD' | 'RETAINED' | 'SHORTLISTED' | 'WITHDRAWN';
  reservePrice: number;
  finalSoldPrice: number | null;
  currency: 'INR';
  purchasingFranchise: string | null;
  purchasingFranchiseId: string | null;
  biddingOrderOrSet?: string;
  sourceUrl: string;
  sourceDocumentTitle: string;
  sourcePublicationDate?: string;
  verificationStatus: 'VERIFIED_OFFICIAL' | 'VERIFIED_HISTORICAL';
}

export interface PlayerAffiliation {
  latestConfirmedFranchise: string | null;
  latestConfirmedFranchiseId: string | null;
  franchiseAffiliationStatus: 'RETAINED' | 'PURCHASED_AT_AUCTION' | 'UNATTACHED';
  latestConfirmedSquadSeason: string;
  latestAuctionStatus: 'SOLD' | 'UNSOLD' | 'RETAINED' | 'AVAILABLE';
  availableForCustomAuction: boolean;
  availabilityLastVerifiedAt: string;
}

export interface PlayerSourceEvidence {
  sourceUrl: string;
  sourceTitle: string;
  publisher: string;
  retrievedAt: string;
  sourceType: string;
  fieldsSupported: string[];
}

export interface Player {
  id: string;
  canonicalName: string;
  fullName?: string;
  normalizedName?: string;
  shortDisplayName?: string;
  dateOfBirth: string;
  calculatedAge: number;
  nationality: string;
  isOverseas: boolean;
  primaryRole: PlayerRole;
  secondaryRole?: string;
  battingStyle: string;
  bowlingStyle: string;
  bowlingType: BowlingType;
  profileSummary: string;
  defaultBasePrice: number; // in whole rupees (e.g. 20000000 = 2 Cr)
  dataCompleteness: 'VERIFIED_HISTORICAL' | 'PARTIAL';
  stats: PlayerStats;
  internationalStatus?: 'CAPPED' | 'UNCAPPED' | 'ASSOCIATE';
  stateAssociation?: string | null;
  internationalCareerSummary?: string;
  profileImageUrl?: string | null;
  officialPlayerProfileUrl?: string | null;
  auctionHistory?: PlayerAuctionEvent[];
  currentAffiliation?: PlayerAffiliation;
  sourceEvidence?: PlayerSourceEvidence;
}

